        }
        return acc;
      },
      {} as Record<string, string>,
    );

    const newToken = cookies[jwtCookieName];
    if (!newToken) {
      // Mark as consumed even if not found, to avoid repeated checks
      this.fastCookieConsumed = true;
      return;
