export function getSessionErrorContext(session?: Session | null): TokenRefreshErrorContext {
  if (!session?.accessToken) {
    return {};
  }

  try {
    const { payload } = decodeJwt(session.accessToken);
    return {
      userId: payload.sub,
      sessionId: payload.sid,
    };
  } catch {
    return {};
  }
}

