    organizationId,
    loginHint,
    prompt,
    state: sealedState,
    codeChallenge: pkce.codeChallenge,
    codeChallengeMethod: pkce.codeChallengeMethod,
    ...(claimNonce && { claimNonce }),
    ...(maxAge !== undefined && { maxAge }),
