          name,
          domain: pkceOptions.domain,
          path: pkceOptions.path,
          sameSite: pkceOptions.sameSite,
          secure: pkceOptions.secure,
        });
      } catch {
        nextCookies.delete(name);
      }
    }

    if (sessionId) {
      redirect(getWorkOS().userManagement.getLogoutUrl({ sessionId, returnTo }));
    } else {
      redirect(returnTo ?? '/');
    }
  }
}

